//! The falsification pass over the recorded divisional charts, which the
//! varga kernel is written from (Phase 4).
//!
//! `03-design/varga-kernel.md` claims there is exactly one evaluator —
//! `varga_sign(sign, part) = table[sign][part]`, with the table generated
//! from four parameters or supplied explicitly — and that of the
//! recording engine's twenty-one charts, eighteen are generated by a
//! linear rule and three supply their table. That is a strong claim and
//! the corpus can decide it outright: a varga's answer is a function of a
//! sidereal longitude alone, and the corpus records both.
//!
//! So this pass derives each chart's table from the corpus itself,
//! independently of any SDK code, and holds the claimed rule to it. It
//! also reports what the corpus **cannot** pin: a rule generalises to
//! cells no recorded body ever fell in, and a table does not, which is
//! the argument for shipping rules.
//!
//! `cargo xtask vargas` writes the page; `check-vargas` regenerates it in
//! memory and fails on any difference.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;
use teistro_core::catalogue::{Rashi, Varga};

use crate::generated::{Output, check, write};
use crate::measure::{Claim, FILL, Verdict, count, fill, table, verdict_of, wrapped};

const PAGE: &str = "docs/03-design/varga-tables-measured.md";
const CHARTS: &str = "fixtures/baseline/charts";
const VARIANTS: &str = "fixtures/baseline/variants";

/// The bodies the engine places in every divisional chart, in its own
/// order. `LAGNA` is one of them, which is what makes the vargottama
/// finding of §6 visible.
const BODIES: [&str; 10] = [
    "SUN", "MOON", "MARS", "MERCURY", "JUPITER", "VENUS", "SATURN", "RAHU", "KETU", "LAGNA",
];

/// A sign's degrees.
const PER_SIGN: f64 = 30.0;

// ── the proposed kernel ────────────────────────────────────────────────────

/// How a sign is sorted into groups, each of which has its own rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Classifier {
    /// One group: every sign alike.
    All,
    /// Odd and even signs, counting Aries as odd.
    Parity,
    /// Movable, fixed and dual.
    Modality,
    /// Fire, earth, air and water.
    Element,
}

impl Classifier {
    /// How many groups it sorts the twelve signs into.
    const fn groups(self) -> u8 {
        match self {
            Classifier::All => 1,
            Classifier::Parity => 2,
            Classifier::Modality => 3,
            Classifier::Element => 4,
        }
    }

    /// Which group a sign belongs to.
    const fn group_of(self, sign: u8) -> usize {
        (sign % self.groups()) as usize
    }

    /// What the page calls it.
    const fn name(self) -> &'static str {
        match self {
            Classifier::All => "all",
            Classifier::Parity => "parity",
            Classifier::Modality => "modality",
            Classifier::Element => "element",
        }
    }
}

/// The multiplier a linear rule puts on the sign.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SignBase {
    /// `a = 0`: count from a fixed sign, which the offset names.
    Fixed,
    /// `a = 1`: count from the sign the body is in.
    Same,
    /// `a = N`: count continuously round the zodiac, the parivritti form.
    Cyclic,
}

impl SignBase {
    /// The multiplier for a chart of `divisions` parts.
    const fn multiplier(self, divisions: u16) -> u32 {
        match self {
            SignBase::Fixed => 0,
            SignBase::Same => 1,
            SignBase::Cyclic => divisions as u32,
        }
    }

    /// What the page calls it.
    const fn name(self) -> &'static str {
        match self {
            SignBase::Fixed => "a fixed sign",
            SignBase::Same => "the sign itself",
            SignBase::Cyclic => "continuously (parivritti)",
        }
    }
}

/// How a part index becomes a sign, for one group.
#[derive(Clone, Copy, Debug)]
enum Map {
    /// `(a·sign + step·part + offset) mod 12`.
    Linear {
        base: SignBase,
        step: u8,
        offset: u8,
    },
    /// One sign per part, listed.
    Table(&'static [u8]),
}

/// Where the parts of a sign begin, for one group.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Spans {
    /// N parts of `30/N` degrees each.
    Equal,
    /// Whole-degree spans, summing to thirty.
    Degrees(&'static [u8]),
}

/// One group's rule.
#[derive(Clone, Copy, Debug)]
struct Group {
    spans: Spans,
    map: Map,
}

/// A divisional chart's proposed rule.
///
/// `divisions` names the chart and is not always how many parts a sign
/// is cut into: D30 is called thirty and its spans cut a sign into five.
/// The part count comes from the spans, and only the equal ones make the
/// two the same.
#[derive(Clone, Copy, Debug)]
struct Scheme {
    varga: Varga,
    divisions: u16,
    classifier: Classifier,
    groups: &'static [Group],
}

/// The equal-span linear group a chart of one rule has.
const fn linear(base: SignBase, step: u8, offset: u8) -> Group {
    Group {
        spans: Spans::Equal,
        map: Map::Linear { base, step, offset },
    }
}

/// An equal-span group whose signs are listed.
const fn listed(signs: &'static [u8]) -> Group {
    Group {
        spans: Spans::Equal,
        map: Map::Table(signs),
    }
}

/// The one-group rules: every sign treated alike.
const ALIKE: [Group; 1] = [linear(SignBase::Same, 0, 0)];
const D3_GROUPS: [Group; 1] = [linear(SignBase::Same, 4, 0)];
const D4_GROUPS: [Group; 1] = [linear(SignBase::Same, 3, 0)];
const STEP_ONE: [Group; 1] = [linear(SignBase::Same, 1, 0)];
const CYCLIC_ONE: [Group; 1] = [linear(SignBase::Cyclic, 1, 0)];

